function wordsOf(s){var t=[];var re=/[a-zA-Z0-9]+/g;var m;while((m=re.exec(s))!==null)t.push(m[0]);return t;}
function camel(words){if(!words.length)return '';return words[0].toLowerCase()+words.slice(1).map(function(w){return w.charAt(0).toUpperCase()+w.slice(1).toLowerCase();}).join('');}
function pascal(words){return words.map(function(w){return w.charAt(0).toUpperCase()+w.slice(1).toLowerCase();}).join('');}
function toKey(label, style, ns){
  var words=wordsOf(label);
  var core;
  if(style==='camel') core=camel(words);
  else if(style==='pascal') core=pascal(words);
  else if(style==='snake') core=words.map(function(w){return w.toLowerCase();}).join('_');
  else if(style==='kebab') core=words.map(function(w){return w.toLowerCase();}).join('-');
  else if(style==='dot') core=words.map(function(w){return w.toLowerCase();}).join('.');
  else if(style==='constant') core=words.map(function(w){return w.toUpperCase();}).join('_');
  else core=words.map(function(w){return w.toLowerCase();}).join('_');
  if(ns){var nw=wordsOf(ns);
    if(style==='camel') core=toKey(ns,'camel')+(core?core.charAt(0).toUpperCase()+core.slice(1):'');
    else if(style==='pascal') core=toKey(ns,'pascal')+core;
    else if(style==='constant') core=nw.map(function(w){return w.toUpperCase();}).join('_')+(core?'_'+core:'');
    else {var sep=style==='kebab'?'-':(style==='dot'?'.':'_'); core=ns.replace(/[^a-zA-Z0-9]+/g,sep).replace(/^_+|_+$/g,'')+(core?sep+core:'');}
  }
  return core;
}
function bulk(text, style, ns, dedup){
  var lines=text.split(/\r\n|\r|\n/);
  var seen={},out=[];
  lines.forEach(function(l){var key=toKey(l,style,ns); if(!key)return; if(dedup){if(seen[key])return;seen[key]=1;} out.push(key);});
  return out;
}
var EXPORTS={wordsOf:wordsOf,toKey:toKey,bulk:bulk,camel:camel,pascal:pascal};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.I18nForgePure = EXPORTS; }
